 inner class Stage:View(this@MainActivity){override fun onDraw(c:Canvas){c.drawColor(Color.BLACK);val b=frame?:return;val s=min(width.toFloat()/b.width,height.toFloat()/b.height);val x=(width-b.width*s)/2;val y=(height-b.height*s)/2;imageRect=RectF(x,y,x+b.width*s,y+b.height*s);c.drawBitmap(b,null,imageRect,paint);c.save();c.translate(x,y);c.scale(s,s);paint.style=Paint.Style.STROKE;paint.strokeWidth=2/s;paint.color=Color.YELLOW;candidates.forEach{c.drawCircle(it.x.toFloat(),it.y.toFloat(),it.r.toFloat(),paint)};seed?.let{paint.color=Color.WHITE;c.drawCircle(it.x.toFloat(),it.y.toFloat(),5/s,paint)};cal.forEach{paint.color=Color.MAGENTA;c.drawCircle(it.first,it.second,5/s,paint)};if(cal.size==2)c.drawLine(cal[0].first,cal[0].second,cal[1].first,cal[1].second,paint);paint.color=Color.CYAN;bg.forEach{c.drawCircle(it.first,it.second,6/s,paint)};paint.color=Color.GREEN;for(i in 1 until pts.size){val a=pts[i-1];val q=pts[i];if(a.segment==q.segment&&q.us-a.us in 1..250000)c.drawLine(a.x.toFloat(),a.y.toFloat(),q.x.toFloat(),q.y.toFloat(),paint)};paint.color=Color.CYAN;for((a,d) in listOf(11 to 12,11 to 13,13 to 15,12 to 14,14 to 16,11 to 23,12 to 24,23 to 24,23 to 25,25 to 27,24 to 26,26 to 28)){val p=joints.getOrNull(a);val q=joints.getOrNull(d);if(p!=null&&q!=null&&p.visibility>=.65&&q.visibility>=.65)c.drawLine(p.x,p.y,q.x,q.y,paint)};paint.style=Paint.Style.FILL;c.restore()}
  override fun onTouchEvent(e:MotionEvent):Boolean{if(e.action!=MotionEvent.ACTION_UP)return true;if(busy||analyzed||!imageRect.contains(e.x,e.y))return true;val b=frame?:return true;val x=(e.x-imageRect.left)*b.width/imageRect.width();val y=(e.y-imageRect.top)*b.height/imageRect.height();if(bgMode){val p=seed?:return true;val rr=radius.text.toString().toIntOrNull()?:24;if(hypot(x-p.x,y-p.y)<rr+12||bg.any{hypot(x-it.first,y-it.second)<24}){status.text="원판 밖 서로 떨어진 두 점 필요";return true};bg.add(x to y);if(bg.size==2){bgMode=false;status.text="고정 배경 두 점 지정 완료"}}else if(calibrating){cal.add(x to y);if(cal.size==2){calibrating=false;status.text="거리 보정점 지정 완료"}}else{val near=candidates.minByOrNull{hypot(it.x-x,it.y-y)};seed=if(near!=null&&hypot(near.x-x,near.y-y)<near.r/2)near.also{radius.setText(it.r.toString())}else Circle(x.roundToInt(),y.roundToInt(),radius.text.toString().toIntOrNull()?:24);bg.clear();bgMode=false;status.text="원판 중심 지정 완료"};controls(false);invalidate();return true}
